<?php if(session_status()!==PHP_SESSION_ACTIVE)session_start();if(empty($_SESSION['usuario_id'])){header('Location: login.php');exit;} ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gestão avançada · BCMR</title><link rel="stylesheet" href="app.css"><style>.page{max-width:1180px;margin:auto;padding:24px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.panel{display:none}.panel.active{display:block}.report-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.mini{padding:14px;border:1px solid var(--border);border-radius:14px}.barrow{display:grid;grid-template-columns:90px 1fr 110px;gap:12px;align-items:center;margin:10px 0}.bar{height:12px;background:#e8edf5;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:var(--primary)}@media(max-width:760px){.report-grid{grid-template-columns:1fr 1fr}.barrow{grid-template-columns:70px 1fr 90px}.page{padding:14px}}</style></head><body><main class="page"><div class="section-head"><div><span class="eyebrow">Grupo BCMR</span><h1>Gestão avançada</h1></div><div><a class="btn" href="index.php">Voltar ao ADM</a> <a class="btn primary" href="public/index.php" target="_blank">Abrir site público</a></div></div><div class="tabs"><button class="btn primary" data-tab="pedidos">Pedidos</button><button class="btn" data-tab="orcamentos">Orçamentos</button><button class="btn" data-tab="financeiro">Financeiro</button><button class="btn" data-tab="integracoes">Integrações</button></div>
<section id="pedidos" class="panel active"><article class="card table-card"><div class="section-head"><h2>Pedidos e reservas</h2></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Status</th><th>Itens</th><th>Total</th><th>Reserva</th><th>Data</th></tr></thead><tbody id="orders"><tr><td colspan="7">Carregando...</td></tr></tbody></table></div></article></section>
<section id="orcamentos" class="panel"><div class="two-col"><article class="card"><h2>Novo orçamento</h2><form id="quoteForm"><div class="form-grid"><label>ID do serviço<input name="servico_id" type="number" min="1" required></label><label>Mão de obra<input name="valor_mao_obra" type="number" step="0.01" min="0" value="0"></label><label>Peças<input name="valor_pecas" type="number" step="0.01" min="0" value="0"></label><label style="grid-column:1/-1">Descrição<textarea name="descricao"></textarea></label></div><button class="btn primary">Criar e enviar</button><div id="quoteMsg" class="modal-message"></div></form></article><article class="card table-card"><h2>Orçamentos recentes</h2><div class="table-wrap"><table><thead><tr><th>Código</th><th>Serviço</th><th>Cliente</th><th>Total</th><th>Status</th></tr></thead><tbody id="quotes"></tbody></table></div></article></div></section>
<section id="financeiro" class="panel"><article class="card"><div class="section-head"><div><span class="eyebrow">12 meses</span><h2>Faturamento consolidado</h2></div></div><div id="financeRows"></div></article></section>
<section id="integracoes" class="panel"><div class="company-grid"><article class="card"><h2>Google Sheets</h2><p>Fila transacional pronta. Configure o webhook e segredo no servidor.</p><code>php jobs/sincronizar_google_sheets.php</code></article><article class="card"><h2>Firebase</h2><p>Fila de push pronta para eventos de atenção e críticos.</p><code>php jobs/enviar_push.php</code></article><article class="card"><h2>Pagamentos</h2><p>Webhook genérico HMAC e adaptadores por gateway preparados.</p><code>api/pagamentos/webhook_generico.php</code></article></div></section></main><script>
let csrf='';const api=async(u,o={})=>{o.headers={...(o.headers||{}),'Content-Type':'application/json'};if(o.method&&o.method!=='GET')o.headers['X-CSRF-Token']=csrf;const r=await fetch(u,o);const j=await r.json();if(!j.status)throw Error(j.mensagem);return j.dados};const fmt=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(+v||0),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('primary',x===b));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.getElementById(b.dataset.tab).classList.add('active');if(b.dataset.tab==='pedidos')orders();if(b.dataset.tab==='orcamentos')quotes();if(b.dataset.tab==='financeiro')finance()});async function orders(){const d=await api('api/pedidos/listar.php');document.getElementById('orders').innerHTML=d.pedidos.map(p=>`<tr><td>${esc(p.codigo)}</td><td>${esc(p.cliente||'-')}</td><td>${esc(p.status)}</td><td>${p.itens}</td><td>${fmt(p.total)}</td><td>${+p.estoque_reservado?'Ativa até '+esc(p.reserva_expira_em):'-'}</td><td>${esc(p.criado_em)}</td></tr>`).join('')||'<tr><td colspan="7">Sem pedidos</td></tr>'}async function quotes(){const d=await api('api/orcamentos/listar.php');document.getElementById('quotes').innerHTML=d.orcamentos.map(q=>`<tr><td>${esc(q.codigo)}</td><td>${esc(q.protocolo)}</td><td>${esc(q.cliente_nome||'-')}</td><td>${fmt(q.valor_total)}</td><td>${esc(q.status)}</td></tr>`).join('')}async function finance(){const d=await api('api/financeiro/resumo.php');const max=Math.max(...d.mensal.map(x=>+x.grupo),1);document.getElementById('financeRows').innerHTML=d.mensal.map(x=>`<div class="barrow"><b>${x.mes}</b><div class="bar"><i style="width:${(+x.grupo/max*100).toFixed(1)}%"></i></div><span>${fmt(x.grupo)}</span></div>`).join('')}document.getElementById('quoteForm').onsubmit=async e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));try{const d=await api('api/orcamentos/criar.php',{method:'POST',body:JSON.stringify(obj)});document.getElementById('quoteMsg').textContent=`${d.codigo} criado. Link público usa token ${d.token_publico}`;quotes()}catch(x){document.getElementById('quoteMsg').textContent=x.message}};(async()=>{const me=await api('api/auth/me.php');csrf=me.csrf;orders()})();
</script></body></html>
